resource "aws_instance" "web" {
  provisioner "file" {
    source      = "app-config.yaml"
    destination = "/etc/app/config.yaml"
  }
}

provisioner "file" {
  source      = "configs/"
  destination = "/etc/app/configs/"
}

provisioner "file" {
  source      = "install.sh"
  destination = "/tmp/install.sh"
}
provisioner "remote-exec" {
  inline = ["chmod +x /tmp/install.sh", "/tmp/install.sh"]
}
